        ):
            credential_id = unquote(
                path[len("/v1/credentials/") : -len("/present-batch")]
            )
            self._post_present_batch(tenant, credential_id)
        elif path.startswith("/v1/credentials/") and path.endswith(
            "/prove"
        ):
            credential_id = unquote(
                path[len("/v1/credentials/") : -len("/prove")]
            )
            self._post_prove(tenant, credential_id)
        elif path.startswith("/v1/credentials/") and path.endswith(
            "/prove-batch"
        ):
            credential_id = unquote(
                path[len("/v1/credentials/") : -len("/prove-batch")]
            )
            self._post_prove_batch(tenant, credential_id)
        elif path.startswith("/v1/proofs/") and path.endswith(
            "/verify"
        ):
            proof_id = unquote(
                path[len("/v1/proofs/") : -len("/verify")]
            )
            self._post_verify_proof(tenant, proof_id)
        elif path == "/v1/presentation-requests":
            self._post_presentation_request(tenant)
        elif path == "/v1/presentations/multi":
            self._post_multi_presentations(tenant)
        elif path.startswith("/v1/presentations/") and path.endswith(
            "/verify"
        ):
            presentation_id = unquote(
                path[len("/v1/presentations/") : -len("/verify")]
            )
            self._post_verify_presentation(
                tenant, presentation_id
            )
        elif path == "/v1/trust/anchors":
            self._post_trust_anchors(tenant)
        elif path == "/v1/trust/anchors/snapshot/verify":
            self._post_trust_anchor_snapshot_verify(tenant)
        elif path == "/v1/trust/anchors/snapshot/verify-batch":
            self._post_trust_anchor_snapshot_verify_batch(tenant)
        elif path == "/v1/trust/anchor-changes/verify":
            self._post_trust_anchor_changes_verify(tenant)
        elif path == "/v1/trust/ac-proof":
            self._post_trust_ac_proof(tenant)
        elif path == "/v1/trust/ac-proof/verify-batch":
            self._post_trust_ac_proof_verify_batch(tenant)
        elif path == "/v1/trust/anchor-changes/sync":
            self._post_trust_anchor_changes_sync(tenant)
        elif path.startswith("/v1/trust/anchors/") and path.endswith(
            "/rotate"
        ):
            did = unquote(
                path[len("/v1/trust/anchors/") : -len("/rotate")]
            )
            self._post_trust_anchor_rotate(tenant, did)
        elif path == "/v1/trust/dids/verify-document":
            self._post_trust_dids_verify_document(tenant)
        elif path == "/v1/trust/dids/verify-document-batch":
            self._post_trust_dids_verify_document_batch(tenant)
        elif path == "/v1/trust/dids/verify-document-synced":
            self._post_trust_dids_verify_document_synced(tenant)
        elif (
            path == "/v1/trust/dids/verify-document-synced-batch"
        ):
            self._post_trust_dids_verify_document_synced_batch(
                tenant
            )
        elif path == "/v1/trust/dids/deactivate-sync":
            self._post_trust_dids_deactivate_sync(tenant)
        elif path == "/v1/trust/dids/deactivate-sync-batch":
            self._post_trust_dids_deactivate_sync_batch(tenant)
        elif path == "/v1/trust/dids/deactivations/manifest/verify":
            self._post_trust_did_deactivations_manifest_verify(tenant)
        elif (
            path
            == "/v1/trust/dids/deactivations/manifest/verify-batch"
        ):
            self._post_trust_did_deactivations_manifest_verify_batch(
                tenant
            )
        elif path == "/v1/trust/verify":
            self._post_trust_verify(tenant)
        elif path == "/v1/trust/credentials/verify":
            self._post_trust_credentials_verify(tenant)
        elif path == "/v1/trust/credentials/verify-with-schema":
            self._post_trust_credentials_verify_with_schema(tenant)
        elif path == "/v1/trust/credentials/verify-synced":
            self._post_trust_credentials_verify_synced(tenant)
        elif (
            path
            == "/v1/trust/credentials/verify-synced-with-status"

        if not 1 <= limit <= 200:
            raise ValidationError(
                "查询参数 limit 须在 1 到 200 之间"
            )
    else:
        limit = 50

    after_values = params.get("after")
    if after_values is not None:
        if len(after_values) != 1:
            raise ValidationError("查询参数 after 只能提供一次")
        after = _parse_nonneg_int(after_values[0], "after")
    else:
        after = 0

    events, next_after = store.list_key_revocations(
        tenant, did, after, limit
    )
    self._send_json(
        200,
        {
            "did": did,
            "events": [
                {
                    "key_version": event.key_version,
                    "reason": event.reason,
                    "updated_at": event.updated_at,
                    "cursor": event.cursor,
                }
                for event in events
            ],
            "next_after": next_after,
        },
    )

def _get_key_history(
    self, tenant: str, did: str, query: str
) -> None:
    # GET /v1/dids/{did}/keys/history?limit=&after=：只读密钥
    # 生命周期历史。响应恰含 did、events、next_after；事件恰含
    # key_version、key_handle、public_key、action、status、
    # updated_at、audit_seq、audit_timestamp、cursor，按 cursor
    # 升序；仅含公钥，绝不暴露私钥。分页参数规则沿用
    # keys/revocations：limit 缺省 50、须 1..200 的 ASCII 十进制
    # 整数；after 缺省 0、须非负；重复/空白/布尔词/小数/符号/
    # Unicode 数字一律 400。未知或他租户 DID 404；已有 DID 无
    # 历史返回空页，空页 next_after 保持 after。纯只读：不写
    # 任何状态、不记审计。
    if not did:
        raise ValidationError("路径缺少 did")
    params = parse_qs(query, keep_blank_values=True)

    limit_values = params.get("limit")
    if limit_values is not None:
        if len(limit_values) != 1:
            raise ValidationError("查询参数 limit 只能提供一次")
        limit = _parse_nonneg_int(limit_values[0], "limit")
        if not 1 <= limit <= 200:
            raise ValidationError(
                "查询参数 limit 须在 1 到 200 之间"
            )
    else:
        limit = 50

    after_values = params.get("after")
    if after_values is not None:
        if len(after_values) != 1:
            raise ValidationError("查询参数 after 只能提供一次")
        after = _parse_nonneg_int(after_values[0], "after")
    else:
        after = 0

    events, next_after = store.list_key_lifecycle(
        tenant, did, after, limit
    )
    self._send_json(
        200,
        {
            "did": did,
            "events": [
                {
                    "key_version": event.key_version,
                    "key_handle": event.key_handle,
                    "public_key": event.public_key,
                    "action": event.action,
                    "status": event.status,
                    "updated_at": event.updated_at,
                    "audit_seq": event.audit_seq,
                    "audit_timestamp": event.audit_timestamp,
                    "cursor": event.cursor,
                }
                for event in events
            ],
            "next_after": next_after,
        },
    )

def _post_rotate_key(self, tenant: str, did: str) -> None:
    data = self._read_json()
    self._require_fields(data, ("key_handle",))
    record = store.rotate_key(tenant, did, data["key_handle"])
    self._send_json(200, self._did_payload(record))

def _post_revoke_key(
    self, tenant: str, did: str, key_version: str
) -> None:
    # POST /v1/dids/{did}/keys/{key_version}/revoke：
    # key_version 须为 ASCII 十进制正整数，否则 400；DID 或版本
    # 不存在（含他租户）404；当前版本 409。请求体空体或 {} 表示
    # 省略 reason；非空时必须恰含 reason，其值由 store 在确认非
    # 重复吊销后校验（字符串裁剪后非空，否则 400），重复吊销时
    # 任何 reason（含非法值）均忽略并返回首次结果。
    if (
        not key_version
        or any(ch < "0" or ch > "9" for ch in key_version)
        or int(key_version) < 1
    ):
        raise ValidationError("路径参数 key_version 必须为 ASCII 十进制正整数")
    data = self._read_optional_json()
    if data:
        extra = sorted(set(data) - {"reason"})
        if extra:
            raise ValidationError(f"多余字段: {', '.join(extra)}")
        if "reason" not in data:
            raise ValidationError("请求体非空时必须恰含字段: reason")
    reason = data["reason"] if data and "reason" in data else REASON_UNSET
    record = store.revoke_key_version(
        tenant, did, int(key_version), reason
    )
    self._send_json(
        200,
        {
            "did": record.did,
            "key_version": record.key_version,
            "status": record.status,
            "reason": record.reason,
            "updated_at": record.updated_at,
        },
    )

def _post_credentials(self, tenant: str) -> None:
    data = self._read_json()
    self._require_fields(data, ("issuer_did", "subject_did"))
    if "claims" not in data:
        raise ValidationError("缺少字段: claims")
    if not isinstance(data["claims"], dict):
        raise ValidationError("字段 claims 必须为 JSON 对象")
    # expires_at 可选：提供时必须为 UTC 秒精度 Z 格式且严格晚于
    # 当前时刻（否则 400）；未提供传哨兵，正文不注入该字段，
    # 凭证保持无期限。
    expires_at = (
        data["expires_at"] if "expires_at" in data else EXPIRES_AT_UNSET
    )
    # schema_id/schema_version 可选，但必须同时出现或同时省略，
    # 否则 400；类型校验在 store 内完成。
    has_schema_id = "schema_id" in data
    has_schema_version = "schema_version" in data
    if has_schema_id != has_schema_version:
        raise ValidationError(
            "schema_id 与 schema_version 必须同时出现或同时省略"
        )
    try:
        record = store.create_credential(
            tenant,
            data["issuer_did"],
            data["subject_did"],
            data["claims"],
            expires_at=expires_at,
            schema_id=(
                data["schema_id"] if has_schema_id else None
            ),
            schema_version=(
                data["schema_version"] if has_schema_version else None
            ),
        )
    except SchemaUnavailableError:
        # 显式引用已弃用/吊销模式版本：统一固定 409 原因，不签发、
        # 不写入、不记审计；未引用或引用 active 版本时走既有路径。
        self._send_json(
            409, {"error": "credential schema unavailable"}
        )
        return
    self._send_json(
        201,
        {
            "credential_id": record.credential_id,
            "signature": record.signature,
            "issuer_key_version": record.body["issuer_key_version"],
        },
    )

@staticmethod
def _schema_payload(record: Any) -> Dict[str, Any]:
    """模式注册/读取成功响应的固定键序负载。"""
    return {
        "schema_id": record.schema_id,
        "version": record.version,
        "issuer_did": record.issuer_did,
        "claim_types": record.claim_types,
        "required_claims": record.required_claims,
        "digest": record.digest,
    }

def _post_credential_schemas(self, tenant: str) -> None:
    # POST /v1/credential-schemas：注册凭证模式约束。请求体恰含
    # schema_id（小写字母开头、小写字母/数字/下划线/连字符、
    # 1..64）、version（正整数）、issuer_did（同租户活动 DID）、
    # claim_types（1..100 个 RFC6901 路径 -> 六类 JSON 类型）、
    # required_claims（其键的不重复子集）。内容非法 400；issuer
    # 未知或跨租户 404；均不写入、不审计。同内容重复注册 200
    # 返回原记录，异内容 409；首次成功 201 并审计。
    data = self._read_json()
    required = (
        "schema_id", "version", "issuer_did",
        "claim_types", "required_claims",
    )
    missing = [field for field in required if field not in data]
    if missing:
        raise ValidationError(f"缺少字段: {', '.join(missing)}")
    extra = sorted(set(data) - set(required))
    if extra:
        raise ValidationError(f"多余字段: {', '.join(extra)}")
    record, created = store.register_credential_schema(
        tenant,
        data["schema_id"],
        data["version"],
        data["issuer_did"],
        data["claim_types"],
        data["required_claims"],
    )
    self._send_json(
        201 if created else 200, self._schema_payload(record)
    )

def _get_credential_schema(
    self, tenant: str, suffix: str, query: str
) -> None:
    # GET /v1/credential-schemas/{schema_id}/{version}
    # ?issuer_did=...：路径段非法（schema_id 格式、version 非
    # ASCII 正整数、段数不对）400；issuer_did 须唯一且非空，
    # 缺失/重复/空值 400；命中 200，模式缺失或跨租户 404
    # （存在性不可探测）。纯只读、不记审计。
    raw_segments = suffix.split("/")
    if len(raw_segments) != 2:
        raise ValidationError(
            "路径必须为 /v1/credential-schemas/{schema_id}/{version}"
        )
    schema_id = unquote(raw_segments[0])
    version_raw = unquote(raw_segments[1])
    if not schema_id or not SCHEMA_ID_RE.fullmatch(schema_id):
        raise ValidationError("路径参数 schema_id 非法")
    if (
        not version_raw
        or any(ch < "0" or ch > "9" for ch in version_raw)
        or int(version_raw) < 1
    ):
        raise ValidationError(
            "路径参数 version 必须为 ASCII 十进制正整数"
        )
    params = parse_qs(query, keep_blank_values=True)

class VCStore:
    """DID、凭证、演示与审计事件的多租户存储。"""

    def __init__(self, path: Optional[str] = None) -> None:
        self.path = path or DEFAULT_STORE_PATH
        self._lock = threading.Lock()
        # tenant_id -> {"dids": {...}, "credentials": {...},
        #               "presentations": {...}}
        self._tenants: Dict[str, Dict[str, Dict[str, Any]]] = {}
        # 全局审计事件（按追加顺序即 seq 升序）
        self._audit: List[Dict[str, Any]] = []
        self._audit_seq: int = 0
        self._load()

    # ------------------------------------------------------------------ #
    # 持久化
    # ------------------------------------------------------------------ #
    def _load(self) -> None:
        data: Dict[str, Any] = {}
        if os.path.exists(self.path):
            with open(self.path, "r", encoding="utf-8") as fh:
                data = json.load(fh)
        if isinstance(data.get("tenants"), dict):
            self._tenants = data["tenants"]
        else:
            # 旧版顶层结构：整体迁入 default 租户桶
            legacy: Dict[str, Any] = {}
            for key in ("dids", "credentials", "presentations"):
                if key in data:
                    legacy[key] = data[key]
            self._tenants = {DEFAULT_TENANT: legacy} if legacy else {}
        self._audit = list(data.get("audit", []))
        if self._audit:
            self._audit_seq = int(
                data.get("audit_seq", self._audit[-1].get("seq", 0))
            )
        else:
            self._audit_seq = int(data.get("audit_seq", 0))
        for bucket in self._tenants.values():
            bucket.setdefault("dids", {})
            bucket.setdefault("credentials", {})
            # 凭证模式（约束）注册表：
            # issuer_did -> schema_id -> version -> 模式行
            bucket.setdefault("credential_schemas", {})
            # 凭证模式版本生命周期历史：
            # issuer_did -> schema_id -> version -> [事件...]
            bucket.setdefault("credential_schema_history", {})
            bucket.setdefault("presentations", {})
            # 验证方展示请求（与单凭证 presentations 相互独立）
            bucket.setdefault("presentation_requests", {})
            # 多凭证组合展示记录（与单凭证 presentations 相互独立）
            bucket.setdefault("multi_presentations", {})
            bucket.setdefault("proofs", {})
            bucket.setdefault("trust_anchors", {})
            bucket.setdefault("credential_status_sync", {})
            bucket.setdefault("imported_credentials", {})
            bucket.setdefault("credential_status_history", {})
            bucket.setdefault("key_revocations", {})
            bucket.setdefault("key_lifecycle", {})
            bucket.setdefault("trust_anchor_history", {})
            bucket.setdefault("trust_anchor_uses_history", {})
            bucket.setdefault("local_credential_status_history", {})
            bucket.setdefault("did_history", {})
            bucket.setdefault("did_deactivation_notices", {})
            bucket.setdefault("did_deactivation_events", [])
            bucket.setdefault("trust_anchor_change_events", [])
            bucket.setdefault("consumed_receipts", {})
            bucket.setdefault("receipt_consumption_events", [])
            bucket.setdefault("synced_receipts", {})
            bucket.setdefault("synced_receipt_consumption_events", [])
            # 凭证状态回执消费历史同步（credential-status/receipt-sync）：
            # synced_credential_status_receipts 为租户内 (verifier_did,
            # nonce) 判重索引；..._events 按 signer_did 保存来源导出行原文。
            # 两者与普通验真回执同步相互独立。
            bucket.setdefault("synced_credential_status_receipts", {})
            bucket.setdefault(
                "synced_credential_status_receipt_consumption_events", []
            )
            bucket.setdefault("synced_anchor_change_pages", {})
            # 跨系统外部演示消费历史同步（presentation-sync）落盘内容：
            # synced_trust_presentations 为按租户的 (issuer_did,
            # presentation_id) 判重索引；..._events 按 signer_did 保存
            # 已落盘的来源导出行原文。
            bucket.setdefault("synced_trust_presentations", {})
            bucket.setdefault(
                "synced_trust_presentation_consumption_events", {}
            )
            # 跨系统外部演示一次性消费判重索引：
            # issuer_did -> presentation_id -> {consumption_id, consumed_at}
            bucket.setdefault("consumed_trust_presentations", {})
            # 演示消费同步进度签名回执一次性消费判重索引：
            # verifier_did -> nonce -> {receipt_id, consumed_at}
            bucket.setdefault("consumed_presentation_sync_receipts", {})
            # 凭证状态同步签名回执一次性消费判重索引：
            # verifier_did -> nonce -> {receipt_id, consumed_at}
            bucket.setdefault("consumed_credential_status_receipts", {})
            # 凭证状态回执消费同步进度签名回执一次性消费判重索引：
            # verifier_did -> nonce -> {receipt_id, consumed_at}。与
            # consumed_credential_status_receipts 相互独立。
            bucket.setdefault(
                "consumed_credential_status_sync_receipts", {}
            )
            # 凭证状态同步签名回执消费历史（租户内跨验证者递增 cursor）。
            bucket.setdefault(
                "credential_status_receipt_consumption_events", []
            )
            # 凭证状态回执消费同步进度签名回执消费历史（租户内跨验证者
            # 递增 cursor），与上者游标空间相互独立。
            bucket.setdefault(
                "credential_status_sync_receipt_consumption_events", []
            )
            # 演示消费同步进度签名回执消费历史（租户内跨验证者递增
            # cursor），独立于其他消费历史游标空间。
            bucket.setdefault(
                "presentation_sync_receipt_consumption_events", []
            )
            for rec in bucket["dids"].values():
                _migrate_did_row(rec)
        # 外部凭证状态历史游标（租户内持久化正整数，按追加递增）。
        # 旧状态文件无该字段时，从已有历史项的最大 cursor 推导。
        self._history_cursor = int(data.get("credential_status_history_cursor", 0))
        if not self._history_cursor:
            max_cursor = 0
            for bucket in self._tenants.values():
                for entries_by_cred in bucket.get(
                    "credential_status_history", {}
                ).values():
                    for entries in entries_by_cred.values():
                        for event in entries:
                            max_cursor = max(
                                max_cursor, int(event.get("cursor", 0))
                            )
            self._history_cursor = max_cursor
        # DID 密钥吊销历史游标：按租户各自维护的持久化正整数
        # （tenant_id -> cursor），同一租户内不同 DID 的吊销事件共享
        # 该游标空间。旧状态文件无该字段时，从各租户已有吊销历史项的
        # 最大 cursor 推导。
        raw_cursors = data.get("key_revocation_cursors", {})
        self._key_revocation_cursors: Dict[str, int] = {
            str(tenant_id): int(cursor)
            for tenant_id, cursor in raw_cursors.items()
            if int(cursor) > 0
        } if isinstance(raw_cursors, dict) else {}
        for tenant_id, bucket in self._tenants.items():
            max_cursor = self._key_revocation_cursors.get(tenant_id, 0)
            for entries in bucket.get("key_revocations", {}).values():
                for event in entries:
                    max_cursor = max(max_cursor, int(event.get("cursor", 0)))
            if max_cursor:
                self._key_revocation_cursors[tenant_id] = max_cursor
        # DID 密钥生命周期历史游标：按租户各自维护的持久化正整数
        # （tenant_id -> cursor），同一租户内不同 DID 的生命周期事件
        # （did.created/key.rotated/key.revoked）共享该游标空间，但与
        # 密钥吊销历史游标空间相互隔离。旧状态文件无该字段时，从各租户
        # 已有生命周期历史项的最大 cursor 推导。
        raw_lifecycle_cursors = data.get("key_lifecycle_cursors", {})
        self._key_lifecycle_cursors: Dict[str, int] = {
            str(tenant_id): int(cursor)
            for tenant_id, cursor in raw_lifecycle_cursors.items()
            if int(cursor) > 0
        } if isinstance(raw_lifecycle_cursors, dict) else {}
        for tenant_id, bucket in self._tenants.items():
            max_cursor = self._key_lifecycle_cursors.get(tenant_id, 0)
            for entries in bucket.get("key_lifecycle", {}).values():
                for event in entries:
                    max_cursor = max(max_cursor, int(event.get("cursor", 0)))
            if max_cursor:
                self._key_lifecycle_cursors[tenant_id] = max_cursor
        # 信任锚点生命周期历史游标：按租户各自维护的持久化正整数
        # （tenant_id -> cursor），同一租户内不同 DID 的锚点事件共享
        # 该游标空间。旧状态文件无该字段时，从各租户已有锚点历史项的
        # 最大 cursor 推导。
        raw_anchor_cursors = data.get("trust_anchor_history_cursors", {})
        self._trust_anchor_history_cursors: Dict[str, int] = {
            str(tenant_id): int(cursor)
            for tenant_id, cursor in raw_anchor_cursors.items()
            if int(cursor) > 0
        } if isinstance(raw_anchor_cursors, dict) else {}
        for tenant_id, bucket in self._tenants.items():
            max_cursor = self._trust_anchor_history_cursors.get(tenant_id, 0)
            for entries in bucket.get("trust_anchor_history", {}).values():
                for event in entries:
                    max_cursor = max(max_cursor, int(event.get("cursor", 0)))
            if max_cursor:
                self._trust_anchor_history_cursors[tenant_id] = max_cursor
        # 信任锚点用途历史游标：按租户各自维护的持久化正整数
        # （tenant_id -> cursor），同一租户内跨 DID 的用途事件
        # （registered/rotated/updated/snapshot）共享该游标空间，与其他
        # 历史游标空间相互独立。旧状态文件无该字段时，从各租户已有用途
        # 历史项的最大 cursor 推导。
        raw_uses_cursors = data.get("trust_anchor_uses_history_cursors", {})
        self._trust_anchor_uses_history_cursors: Dict[str, int] = {
            str(tenant_id): int(cursor)
            for tenant_id, cursor in raw_uses_cursors.items()
            if int(cursor) > 0
        } if isinstance(raw_uses_cursors, dict) else {}
        for tenant_id, bucket in self._tenants.items():
            max_cursor = self._trust_anchor_uses_history_cursors.get(
                tenant_id, 0
            )

def do_GET(self) -> None:  # noqa: N802
    try:
        parsed = urlparse(self.path)
        path = parsed.path.rstrip("/") or "/"
        if path in ("/health", "/healthz"):
            self._send_json(200, {"status": "ok"})
            return
        if not path.startswith("/v1"):
            self._send_error(404, f"无此路径: {path}")
            return
        # 仅 /v1 路由受租户头约束
        if (
            path
            == "/v1/trust/presentation-sync/receipt/consumptions"
            and self.headers.get("X-Tenant-ID") == ""
        ):
            raise ValidationError("请求非法")
        tenant = self._tenant_id()
        if path == "/v1/audit":
            self._get_audit(tenant, parsed.query)
        elif path == "/v1/audit/manifest":
            self._get_audit_manifest(tenant, parsed.query)
        elif path == "/v1/presentation-requests" or (
            path.startswith("/v1/presentation-requests/")
        ):
            request_id = unquote(
                path[len("/v1/presentation-requests/") :]
            ) if path.startswith("/v1/presentation-requests/") else ""
            if not request_id:
                self._send_error(404, f"无此路径: {path}")
            else:
                self._get_presentation_request(tenant, request_id)
        elif path.startswith("/v1/dids/") and path.endswith(
            "/document"
        ):
            did = unquote(
                path[len("/v1/dids/") : -len("/document")]
            )
            self._get_did_document(tenant, did, parsed.query)
        elif path.startswith("/v1/dids/") and "/keys/" in path and (
            path.endswith("/status")
            or path.endswith("/keys/revocations")
            or path.endswith("/keys/history")
        ):
            middle = path[len("/v1/dids/") :]
            did_raw, sep, rest = middle.partition("/keys/")
            did = unquote(did_raw)
            if rest == "revocations":
                self._get_key_revocations(
                    tenant, did, parsed.query
                )
            elif rest == "history":
                self._get_key_history(
                    tenant, did, parsed.query
                )
            else:
                key_version = unquote(
                    rest[: -len("/status")]
                )
                self._get_key_version_status(
                    tenant, did, key_version
                )
        elif path.startswith("/v1/dids/") and path.endswith("/status"):
            did = unquote(
                path[len("/v1/dids/") : -len("/status")]
            )
            self._get_did_status(tenant, did)
        elif path.startswith("/v1/dids/") and path.endswith("/history"):
            did = unquote(
                path[len("/v1/dids/") : -len("/history")]
            )
            self._get_did_history(tenant, did, parsed.query)
        elif path.startswith("/v1/dids/"):
            self._get_did(tenant, unquote(path[len("/v1/dids/") :]))
        elif path.startswith("/v1/credential-schemas/"):
            schema_suffix = path[len("/v1/credential-schemas/") :]
            if schema_suffix.endswith("/status"):
                self._get_credential_schema_status(
                    tenant,
                    schema_suffix[: -len("/status")],
                    parsed.query,
                )
            elif schema_suffix.endswith("/history"):
                self._get_credential_schema_history(
                    tenant,
                    schema_suffix[: -len("/history")],
                    parsed.query,
                )
            else:
                self._get_credential_schema(
                    tenant, schema_suffix, parsed.query
                )
        elif path.startswith("/v1/credentials/") and path.endswith(
            "/status/history"
        ):
            credential_id = unquote(
                path[
                    len("/v1/credentials/") : -len("/status/history")
                ]
            )
            self._get_credential_status_history(
                tenant, credential_id, parsed.query
            )
        elif path.startswith("/v1/credentials/") and path.endswith(
            "/status"
        ):
            credential_id = unquote(
                path[len("/v1/credentials/") : -len("/status")]
            )
            self._get_credential_status(tenant, credential_id)
        elif path.startswith("/v1/credentials/"):
            self._get_credential(
                tenant, unquote(path[len("/v1/credentials/") :])
            )
        elif path == "/v1/trust/anchors":
            self._get_trust_anchor_discovery(tenant, parsed.query)
        elif path == "/v1/trust/anchor-changes":
            self._get_trust_anchor_changes(tenant, parsed.query)
        elif path == "/v1/trust/ac-proof":
            self._get_trust_ac_proof(tenant, parsed.query)
        elif path == "/v1/trust/anchor-changes/sync-history":
            self._get_trust_anchor_changes_sync_history(
                tenant, parsed.query
            )
        elif path == "/v1/trust/anchor-changes/synced-state":
            self._get_trust_anchor_changes_synced_state(
                tenant, parsed.query
            )
        elif path == "/v1/trust/presentation-sync/history":
            self._get_trust_presentation_sync_history(
                tenant, parsed.query
            )
        elif path == "/v1/trust/presentation-sync/receipt":
            self._get_trust_presentation_sync_receipt(
                tenant, parsed.query
            )
        elif (
            path
            == "/v1/trust/presentation-sync/receipt/consumptions"
        ):
            self._get_trust_presentation_sync_receipt_consumptions(
                tenant, parsed.query
            )
        elif path == "/v1/trust/anchors/snapshot":
            self._get_trust_anchor_snapshot(tenant, parsed.query)
        elif path == "/v1/trust/dids/deactivations":
            self._get_trust_did_deactivations(tenant, parsed.query)
        elif (
            path
            == (
                "/v1/trust/credential-status/receipt/consumptions"
                "/export"
            )
        ):
            self._get_trust_credential_status_receipt_consumptions_export(
                tenant, parsed.query
            )
        elif (
            path
            == "/v1/trust/credential-status/receipt/consumptions"
            "/manifest"
        ):
            self._get_trust_credential_status_receipt_consumptions_manifest(
                tenant, parsed.query
            )
        elif (
            path
            == "/v1/trust/credential-status/receipt-sync/history"
        ):
            self._get_trust_credential_status_receipt_sync_history(
                tenant, parsed.query
            )
        elif (
            path
            == "/v1/trust/credential-status/receipt-sync/receipt"
        ):
            self._get_trust_credential_status_receipt_sync_receipt(
                tenant, parsed.query
            )
        elif (

            f"查询参数 {field} 必须为 UTC 秒精度 Z 时间"
            "（YYYY-MM-DDTHH:MM:SSZ）"
        )
    try:
        datetime.strptime(raw, "%Y-%m-%dT%H:%M:%SZ").replace(
            tzinfo=timezone.utc
        )
    except (ValueError, TypeError):
        raise ValidationError(
            f"查询参数 {field} 必须为 UTC 秒精度 Z 时间"
            "（YYYY-MM-DDTHH:MM:SSZ）"
        )
    return raw


def _anchor_change_event_obj(event: Any) -> Dict[str, Any]:
    """锚点变更事件按变更流协议构造固定键序对象。"""
    return {
        "cursor": event.cursor,
        "action": event.action,
        "did": event.did,
        "key_version": event.key_version,
        "public_key": event.public_key,
        "status": event.status,
        "uses": event.uses,
    }


def _anchor_proof_leaf_hash(event_obj: Dict[str, Any]) -> str:
    """叶哈希 = SHA-256(0x00 || 事件规范 JSON 的 UTF-8)，返回小写 hex。"""
    return hashlib.sha256(
        b"\x00" + crypto.canonicalize(event_obj)
    ).hexdigest()


def _anchor_proof_parent_hash(left_hex: str, right_hex: str) -> str:
    """父哈希 = SHA-256(0x01 || 左 || 右)，左右为 32 字节摘要，返回小写 hex。"""
    return hashlib.sha256(
        b"\x01" + bytes.fromhex(left_hex) + bytes.fromhex(right_hex)
    ).hexdigest()


def _anchor_proof_build(
    leaf_hashes: List[str], index: int
) -> Tuple[str, List[Dict[str, str]]]:
    """以 cursor 升序叶序列对 index 处目标建 Merkle 包含证明。

    奇数层复制末项；返回 (root, path)，path 自叶向根，每项
    {"side": 兄弟所在侧, "hash": 兄弟哈希}。单叶时 root 即叶哈希、
    path 为空。
    """
    path: List[Dict[str, str]] = []
    level = list(leaf_hashes)
    current = index
    while len(level) > 1:
        if len(level) % 2 == 1:
            # 奇数末项复制后再配对。
            level.append(level[-1])
        if current % 2 == 0:
            path.append({"side": "right", "hash": level[current + 1]})
        else:
            path.append({"side": "left", "hash": level[current - 1]})
        next_level = [
            _anchor_proof_parent_hash(level[pos], level[pos + 1])
            for pos in range(0, len(level), 2)
        ]
        level = next_level
        current //= 2
    return level[0], path


def _anchor_proof_recompute_root(
    event_obj: Dict[str, Any], path: List[Dict[str, str]]
) -> str:
    """按 path 自叶向根重算 root（与建树同一叶/父哈希规则）。"""
    current = _anchor_proof_leaf_hash(event_obj)
    for item in path:
        sibling = item["hash"]
        if item["side"] == "left":
            current = _anchor_proof_parent_hash(sibling, current)
        else:
            current = _anchor_proof_parent_hash(current, sibling)
    return current


def build_handler(store: VCStore) -> type:
    """构造绑定给定 store 的请求处理器类。"""

    class Handler(BaseHTTPRequestHandler):
        server_version = "VCBackend/0.1"

        # ------------------------------------------------------------ #
